import type { FilterForm } from 'models/Filters';

export type CommercialResultsFormTier = 1 | 2 | 3;

/**
 * Fields that show skeleton while a tiered preset refetch runs.
 * Tier 3 always skeletons all brand-dependent dimensions (including brand switches).
 * Clearing brand (3 → 2) skeletons all fields that revert to the country-wide union.
 */
export function getCommercialPresetSkeletonFieldKeys(
  targetTier: CommercialResultsFormTier,
  previousTier?: CommercialResultsFormTier,
): string[] {
  if (targetTier === 3) {
    return ['region', 'channel', 'pack_type', 'sub_brands', 'sku'];
  }

  if (targetTier === 2) {
    if (previousTier === 3) {
      return ['region', 'channel', 'pack_type', 'sub_brands', 'sku'];
    }
    return ['region', 'brands', 'channel', 'pack_type'];
  }

  if (previousTier === 2 || previousTier === 3) {
    return ['region', 'brands', 'channel', 'pack_type', 'sub_brands', 'sku'];
  }

  return [];
}

/**
 * Skeleton fields when flat drivers (region/channel/pack_type) change within the same tier.
 */
export function getCommercialPresetSkeletonFieldKeysForFlatDriverChange(
  targetTier: CommercialResultsFormTier,
): string[] {
  if (targetTier === 3) {
    return ['brands', 'region', 'channel', 'pack_type', 'sub_brands', 'sku'];
  }

  if (targetTier === 2) {
    return ['brands', 'region', 'channel', 'pack_type'];
  }

  return [];
}

/**
 * Tier follows **form** (live drawer), aligned with BFF query composition.
 *
 * - Tier 1: global country (ABI) or unset.
 * - Tier 2: concrete country, brand still “open” (`All` / empty).
 * - Tier 3: concrete country + any other `brands` value.
 */
export function resolveCommercialResultsRefreshTier(
  form: FilterForm | undefined,
): CommercialResultsFormTier {
  const country = form?.country;
  const brand = form?.brands;

  const tier1 =
    country == null ||
    country === '' ||
    String(country).toUpperCase() === 'ABI';
  if (tier1) return 1;

  const brandAll =
    brand == null || brand === '' || String(brand).toUpperCase() === 'ALL';
  if (brandAll) return 2;

  return 3;
}
